const trainingDetails={
  curl:{tension:'La carga en la mano crea un momento externo de extensión en el codo. Braquial y bíceps producen el momento flexor; la demanda cambia con la distancia perpendicular entre carga y eje.',recruitment:'Una resistencia exigente o una serie con esfuerzo creciente puede requerir más unidades motoras de los flexores del codo.'},
  tricepsext:{tension:'La resistencia tiende a flexionar el codo; el tríceps se opone durante la extensión y controla el regreso. La longitud de su cabeza larga cambia con el hombro elevado.',recruitment:'La demanda de fuerza en la extensión puede aumentar el reclutamiento del tríceps; el gesto sin carga no lo cuantifica.'},
  lateralraise:{tension:'El peso del brazo o de una mancuerna genera un momento aductor creciente al alejarse del eje del hombro. Deltoides medio y supraespinoso crean el momento abductor.',recruitment:'Una carga compatible con el control del hombro y un esfuerzo alto pueden aumentar el reclutamiento de abductores.'},
  overheadpress:{tension:'La carga externa exige momentos en hombro y codo; deltoides y tríceps producen el empuje, mientras tronco y cintura escapular estabilizan.',recruitment:'Con mayor demanda de fuerza participan más unidades motoras de los músculos impulsores; la técnica cambia cómo se reparte la exigencia.'},
  row:{tension:'La resistencia tira de las manos hacia delante y genera momentos en hombro y codo. Dorsal ancho, redondo mayor y flexores del codo se oponen durante la tracción.',recruitment:'El reclutamiento puede aumentar con una tracción exigente o con fatiga progresiva; el visor no mide activación.'},
  lunge:{tension:'El peso corporal y una carga adicional generan momentos externos de flexión en cadera y rodilla. Glúteos y cuádriceps controlan el descenso y extienden al subir.',recruitment:'La pierna delantera puede necesitar alta producción de fuerza si la carga y el esfuerzo lo exigen; no existe un valor fijo por ejercicio.'},
  heelraise:{tension:'El peso del cuerpo tiende a llevar el tobillo hacia dorsiflexión alrededor del apoyo del antepié. Sóleo y gastrocnemio crean el momento plantarflexor.',recruitment:'Más carga o esfuerzo en las repeticiones puede requerir más unidades motoras de los plantarflexores.'},
  deadlift:{tension:'Al inclinar el tronco, la carga y el peso de los segmentos crean momentos flexores en cadera y tronco. Glúteos e isquiotibiales extienden la cadera; los erectores estabilizan.',recruitment:'Una carga exigente aumenta la demanda de fuerza extensora, aunque la cantidad reclutada depende de técnica, carga y fatiga.'},
  chestpress:{tension:'La resistencia dirigida hacia atrás crea un momento externo en hombro y codo. Pectoral mayor, deltoides anterior y tríceps generan el empuje.',recruitment:'El esfuerzo elevado puede requerir mayor reclutamiento de pectoral y tríceps; el ejercicio por sí solo no garantiza un nivel concreto.'},
  pullup:{tension:'El peso corporal tira del tronco hacia abajo. Dorsal ancho y flexores del codo producen momentos que aproximan el cuerpo a las manos; escápula y tronco estabilizan.',recruitment:'Si el peso corporal representa una demanda elevada, puede requerirse alto reclutamiento de los músculos de tracción.'},
  rdl:{tension:'La carga y el tronco generan un momento flexor de cadera que crece al aumentar su brazo de momento. Glúteo mayor e isquiotibiales controlan el descenso y extienden en el ascenso.',recruitment:'Una carga desafiante puede aumentar el reclutamiento de extensores de cadera; sentir estiramiento no equivale a medir tensión o activación.'},
  legextension:{tension:'La resistencia distal intenta flexionar la rodilla. El cuádriceps genera el momento extensor; una leva real modificaría el brazo de momento en cada ángulo.',recruitment:'Una resistencia exigente o una serie próxima al límite de rendimiento puede elevar el reclutamiento del cuádriceps.'},
  legcurl:{tension:'La resistencia distal intenta extender la rodilla. Los isquiotibiales producen el momento flexor y controlan la vuelta; la posición de cadera modifica su longitud.',recruitment:'El reclutamiento de isquiotibiales puede crecer con carga y fatiga; el visor no distingue unidades motoras individuales.'}
};
for(const movement of extraMovements){if(trainingDetails[movement.id])movement.trainingLoad=trainingDetails[movement.id]}
